rewrite-uri.template:
@{
        var path = context.Request.Url.Path;

        /* Health del ingress vía APIM */
        if (path.Equals("/_ingress/health"))
        {
            return "/healthz";
        }

        /* Si publicas con /cardops delante, quítalo */
        if (path.StartsWith("/cardops"))
        {
            return path.Substring(8);
        }

        return path;
    }
